source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    palette = sorted({g[r][c] for r in range(3, h) for c in range(6, w) if g[r][c] != 0})
    cycle = [x for x in palette if x % 2 == 1] + [x for x in palette if x % 2 == 0]
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0:
                continue
            if r < 2 or c < 2:
                g[r][c] = 1
            elif r == 2 or c == 2:
                g[r][c] = 4
            else:
                anchors = [x for x in range(3, w) if g[r][x] in cycle]
                if anchors:
                    a = min(anchors, key=lambda x: abs(x - c))
                    g[r][c] = cycle[(cycle.index(g[r][a]) + c - a) % len(cycle)]
                else:
                    anchors = [x for x in range(3, h) if g[x][c] in cycle]
                    a = min(anchors, key=lambda x: abs(x - r))
                    g[r][c] = cycle[(cycle.index(g[a][c]) + r - a) % len(cycle)]
    return g
'''
